package com.loja.checkout;

import com.loja.checkout.enums.CodigoErro;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.client.TestRestTemplate;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class CheckoutControllerTest {

    @Autowired
    private TestRestTemplate restTemplate;

    @Test
    void testPedidoInvalido_CarrinhoVazio() {
        String requestBody = """
            {
                "itens": [],
                "modalidadeEntrega": "EXPRESSA",
                "formaPagamento": "PIX",
                "nivelClube": "BRONZE",
                "regiao": "SUDESTE"
            }
            """;

        ResponseEntity<Map> response = restTemplate.postForEntity(
            "/checkout/resumo",
            requestBody,
            Map.class
        );

        assertEquals(HttpStatus.BAD_REQUEST, response.getStatusCode());
        assertEquals(CodigoErro.PEDIDO_INVALIDO.name(), response.getBody().get("erro"));
    }

    @Test
    void testNivelClubeInvalido() {
        String requestBody = """
            {
                "itens": [
                    {
                        "nome": "Camiseta",
                        "precoUnitario": 79.90,
                        "quantidade": 1,
                        "pesoKg": 0.30
                    }
                ],
                "modalidadeEntrega": "EXPRESSA",
                "formaPagamento": "PIX",
                "nivelClube": "DIAMANTE",
                "regiao": "SUDESTE"
            }
            """;

        ResponseEntity<Map> response = restTemplate.postForEntity(
            "/checkout/resumo",
            requestBody,
            Map.class
        );

        assertEquals(HttpStatus.BAD_REQUEST, response.getStatusCode());
        assertEquals(CodigoErro.NIVEL_CLUBE_INVALIDO.name(), response.getBody().get("erro"));
    }

    @Test
    void testRegiaoInvalida() {
        String requestBody = """
            {
                "itens": [
                    {
                        "nome": "Camiseta",
                        "precoUnitario": 79.90,
                        "quantidade": 1,
                        "pesoKg": 0.30
                    }
                ],
                "modalidadeEntrega": "EXPRESSA",
                "formaPagamento": "PIX",
                "nivelClube": "BRONZE",
                "regiao": "ANTARTIDA"
            }
            """;

        ResponseEntity<Map> response = restTemplate.postForEntity(
            "/checkout/resumo",
            requestBody,
            Map.class
        );

        assertEquals(HttpStatus.BAD_REQUEST, response.getStatusCode());
        assertEquals(CodigoErro.REGIAO_INVALIDA.name(), response.getBody().get("erro"));
    }

    @Test
    void testModalidadeInvalida() {
        String requestBody = """
            {
                "itens": [
                    {
                        "nome": "Camiseta",
                        "precoUnitario": 79.90,
                        "quantidade": 1,
                        "pesoKg": 0.30
                    }
                ],
                "modalidadeEntrega": "DRONE",
                "formaPagamento": "PIX",
                "nivelClube": "BRONZE",
                "regiao": "SUDESTE"
            }
            """;

        ResponseEntity<Map> response = restTemplate.postForEntity(
            "/checkout/resumo",
            requestBody,
            Map.class
        );

        assertEquals(HttpStatus.BAD_REQUEST, response.getStatusCode());
        assertEquals(CodigoErro.MODALIDADE_INVALIDA.name(), response.getBody().get("erro"));
    }

    @Test
    void testModalidadeIndisponivel_MotoboyAcima5Kg() {
        String requestBody = """
            {
                "itens": [
                    {
                        "nome": "Produto Pesado",
                        "precoUnitario": 100.00,
                        "quantidade": 2,
                        "pesoKg": 3.00
                    }
                ],
                "modalidadeEntrega": "MOTOBOY",
                "formaPagamento": "PIX",
                "nivelClube": "BRONZE",
                "regiao": "SUDESTE"
            }
            """;

        ResponseEntity<Map> response = restTemplate.postForEntity(
            "/checkout/resumo",
            requestBody,
            Map.class
        );

        assertEquals(HttpStatus.BAD_REQUEST, response.getStatusCode());
        assertEquals(CodigoErro.MODALIDADE_INDISPONIVEL.name(), response.getBody().get("erro"));
    }

    @Test
    void testCupomInvalido() {
        String requestBody = """
            {
                "itens": [
                    {
                        "nome": "Camiseta",
                        "precoUnitario": 79.90,
                        "quantidade": 1,
                        "pesoKg": 0.30
                    }
                ],
                "modalidadeEntrega": "EXPRESSA",
                "cupom": "CUPOMINEXISTENTE",
                "formaPagamento": "PIX",
                "nivelClube": "BRONZE",
