            {
                "itens": [
                    {
                        "nome": "Camiseta",
                        "precoUnitario": 79.90,
                        "quantidade": 1,
                        "pesoKg": 0.30
                    }
                ],
                "modalidadeEntrega": "EXPRESSA",
